using Api.Services.DataSources; using global::Microsoft.Data.SqlClient; using Microsoft.Extensions.Logging; using Microsoft.Extensions.Logging.Abstractions; using Testcontainers.MsSql; using Xunit;  namespace Api.Tests;  public sealed class SqlServerSourceDataSessionIntegrationTests : IClassFixture<SqlServerContainerFixture> {     private readonly SqlServerContainerFixture _fixture;      public SqlServerSourceDataSessionIntegrationTests(SqlServerContainerFixture fixture)     {         _fixture = fixture;     }      [Fact]     public async Task GetTablesAndColumnsAsync_DiscoversReservedAndUnicodeObjects()     {         if (!_fixture.IsAvailable)             return;          var connectionString = await _fixture.CreateSeededConnectionStringAsync();         await using var session = new SqlServerSourceDataSession(connectionString, NullLogger<SqlServerSourceDataSession>.Instance);          await session.TestConnectionAsync();         var tables = await session.GetTablesAsync();         var columns = await session.GetColumnsAsync("[sales].[Order]");         var columnDefinitions = await session.GetColumnDefinitionsAsync("[sales].[Order]");          Assert.Contains("[sales].[Order]", tables);         Assert.Contains("[dbo].[Каталог]", tables);         Assert.Equal(["ID", "Updated At", "Naziv", "Price", "Optional Note"], columns);         Assert.Collection(             columnDefinitions.OrderBy(column => column.Ordinal),             column =>             {                 Assert.Equal("ID", column.Name);                 Assert.Equal("bigint", column.SourceType);                 Assert.False(column.IsNullable);                 Assert.Equal(0, column.Ordinal);             },             column =>             {                 Assert.Equal("Updated At", column.Name);                 Assert.Equal("datetime2", column.SourceType);                 Assert.False(column.IsNullable);                 Assert.Equal(1, column.Ordinal);             },             column =>             {                 Assert.Equal("Naziv", column.Name);                 Assert.Equal("nvarchar", column.SourceType);                 Assert.False(column.IsNullable);                 Assert.Equal(2, column.Ordinal);             },             column =>             {                 Assert.Equal("Price", column.Name);                 Assert.Equal("decimal", column.SourceType);                 Assert.True(column.IsNullable);                 Assert.Equal(3, column.Ordinal);             },             column =>             {                 Assert.Equal("Optional Note", column.Name);                 Assert.Equal("nvarchar", column.SourceType);                 Assert.True(column.IsNullable);                 Assert.Equal(4, column.Ordinal);             });         Assert.Equal("sqlserver", session.Provider);         Assert.Equal("sqlclient", session.Mode);         Assert.DoesNotContain("Password=", session.SourceIdentity, StringComparison.OrdinalIgnoreCase);     }      [Fact]     public async Task ReadRowsAsync_ProducesDeterministicFullAndIncrementalResults()     {         if (!_fixture.IsAvailable)             return;          var connectionString = await _fixture.CreateSeededConnectionStringAsync();         await using var session = new SqlServerSourceDataSession(connectionString, NullLogger<SqlServerSourceDataSession>.Instance);          var fullQuery = new SourceReadQuery         {             CursorMode = "id",             IdAliases = ["id"]         };          var fullRows = await ReadAllAsync(session.ReadRowsAsync("[sales].[Order]", fullQuery));         Assert.Equal([1L, 2L, 3L], fullRows.Select(GetId));         Assert.Equal(["Crna čizma", "Plava cipela", "Žuta sandala"], fullRows.Select(GetName));         Assert.Equal(12.50m, GetDecimal(fullRows[0], "Price"));         Assert.Null(GetValue(fullRows[1], "Optional Note"));          var incrementalQuery = new SourceReadQuery         {             CursorMode = "timestamp_then_id",             CursorTimestampUtc = new DateTime(2026, 8, 27, 9, 0, 0, DateTimeKind.Utc),             CursorTieBreakerId = 1,             TimestampAliases = ["updatedat"],             IdAliases = ["id"]         };          var incrementalRows = await ReadAllAsync(session.ReadRowsAsync("[sales].[Order]", incrementalQuery));         Assert.Equal([2L, 3L], incrementalRows.Select(GetId));          var count = await session.TryGetRowCountAsync("[sales].[Order]");         Assert.True(count.IsExact);         Assert.Equal(3, count.Count);     }      [Fact]     public async Task TryGetRowCountAsync_TimesOut_WhenReadIsBlocked()     {         if (!_fixture.IsAvailable)             return;          var connectionString = await _fixture.CreateSeededConnectionStringAsync();         await using var locker = new SqlConnection(connectionString);         await locker.OpenAsync();         await using var transaction = await locker.BeginTransactionAsync();         await using (var lockCommand = new SqlCommand(             "SELECT TOP (1) 1 FROM [sales].[Order] WITH (TABLOCKX, HOLDLOCK);",             locker,             (SqlTransaction)transaction))         {             await lockCommand.ExecuteScalarAsync();         }          try         {             await using var session = new SqlServerSourceDataSession(                 connectionString,                 NullLogger<SqlServerSourceDataSession>.Instance,                 commandTimeoutSeconds: 1);              var ex = await Assert.ThrowsAsync<SqlException>(() => session.TryGetRowCountAsync("[sales].[Order]"));             Assert.True(                 ex.Number == -2 || ex.Message.Contains("timeout", StringComparison.OrdinalIgnoreCase),                 $"Expected SQL timeout, got {ex.Number}: {ex.Message}");         }         finally         {             await transaction.RollbackAsync();         }     }      [Fact]     public async Task ReadRowsAsync_HonorsCancellation_WhenReadIsBlocked()     {         if (!_fixture.IsAvailable)             return;          var connectionString = await _fixture.CreateSeededConnectionStringAsync();         await using var locker = new SqlConnection(connectionString);         await locker.OpenAsync();         await using var transaction = await locker.BeginTransactionAsync();         await using (var lockCommand = new SqlCommand(             "SELECT TOP (1) 1 FROM [sales].[Order] WITH (TABLOCKX, HOLDLOCK);",             locker,             (SqlTransaction)transaction))         {             await lockCommand.ExecuteScalarAsync();         }          try         {             await using var session = new SqlServerSourceDataSession(                 connectionString,                 NullLogger<SqlServerSourceDataSession>.Instance,                 commandTimeoutSeconds: 30);             using var cts = new CancellationTokenSource(TimeSpan.FromMilliseconds(200));              var ex = await Record.ExceptionAsync(async () =>             {                 await foreach (var _ in session.ReadRowsAsync("[sales].[Order]", cts.Token))                 {                 }             });              Assert.NotNull(ex);             Assert.True(                 ex is OperationCanceledException                 || ex is SqlException sqlEx && sqlEx.Message.Contains("cancel", StringComparison.OrdinalIgnoreCase),                 ex.ToString());         }         finally         {             await transaction.RollbackAsync();         }     }      [Fact]     public async Task TestConnectionAsync_LogsSafeIdentityWithoutLeakingCredentials()     {         if (!_fixture.IsAvailable)             return;          var password = "Trendplus_Strong_123!";         var connectionString = await _fixture.CreateSeededConnectionStringAsync(passwordOverride: password);         var sink = new ListLogger<SqlServerSourceDataSession>();          await using var session = new SqlServerSourceDataSession(connectionString, sink);         await session.TestConnectionAsync();          var messages = sink.Messages;         Assert.NotEmpty(messages);         Assert.DoesNotContain(messages, message => message.Contains(password, StringComparison.Ordinal));         Assert.DoesNotContain(messages, message => message.Contains("Password=", StringComparison.OrdinalIgnoreCase));         Assert.Contains(messages, message => message.Contains("sqlserver://", StringComparison.OrdinalIgnoreCase));     }      private static object? GetValue(SourceDataRow row, string alias)     {         Assert.True(row.TryGetValue(alias, out var value));         return value;     }      private static long GetId(SourceDataRow row) => Convert.ToInt64(GetValue(row, "ID"));      private static string GetName(SourceDataRow row) => Assert.IsType<string>(GetValue(row, "Naziv"));      private static decimal GetDecimal(SourceDataRow row, string alias) => Convert.ToDecimal(GetValue(row, alias));      private static async Task<List<SourceDataRow>> ReadAllAsync(IAsyncEnumerable<SourceDataRow> rows)     {         var result = new List<SourceDataRow>();         await foreach (var row in rows)             result.Add(row);          return result;     } }  public sealed class SqlServerContainerFixture : IAsyncLifetime {     private MsSqlContainer? _container;      public bool IsAvailable { get; private set; }      public string AdminConnectionString => _container?.GetConnectionString() ?? string.Empty;      public async Task InitializeAsync()     {         try         {             _container = new MsSqlBuilder()                 .WithImage("mcr.microsoft.com/mssql/server:2022-latest")                 .WithPassword("Trendplus_Strong_123!")                 .Build();              await _container.StartAsync();             IsAvailable = true;         }         catch (Exception ex)         {             IsAvailable = false;             if (string.Equals(Environment.GetEnvironmentVariable("CI"), "true", StringComparison.OrdinalIgnoreCase))             {                 throw new InvalidOperationException(                     "SQL Server integration tests are mandatory in CI when QDB03 is active, but the Testcontainers fixture could not start.",                     ex);             }         }     }      public async Task DisposeAsync()     {         if (_container is not null)             await _container.DisposeAsync();     }      public async Task<string> CreateSeededConnectionStringAsync(string? passwordOverride = null)     {         if (!IsAvailable)             return string.Empty;          var databaseName = $"tp_qdb03_{Guid.NewGuid():N}";         var builder = new SqlConnectionStringBuilder(AdminConnectionString)         {             InitialCatalog = "master"         };         if (!string.IsNullOrWhiteSpace(passwordOverride))             builder.Password = passwordOverride;          await using var connection = new SqlConnection(builder.ConnectionString);         await connection.OpenAsync();          await using (var createDb = new SqlCommand($"CREATE DATABASE [{databaseName}];", connection))         {             await createDb.ExecuteNonQueryAsync();         }          var dbBuilder = new SqlConnectionStringBuilder(AdminConnectionString)         {             InitialCatalog = databaseName         };         if (!string.IsNullOrWhiteSpace(passwordOverride))             dbBuilder.Password = passwordOverride;          await using var seeded = new SqlConnection(dbBuilder.ConnectionString);         await seeded.OpenAsync();          var setupStatements = new[]         {             "CREATE SCHEMA sales;",             """             CREATE TABLE [sales].[Order] (                 [ID] BIGINT NOT NULL PRIMARY KEY,                 [Updated At] DATETIME2 NOT NULL,                 [Naziv] NVARCHAR(100) NOT NULL,                 [Price] DECIMAL(18,2) NULL,                 [Optional Note] NVARCHAR(100) NULL             );             """,             """             INSERT INTO [sales].[Order] ([ID], [Updated At], [Naziv], [Price], [Optional Note]) VALUES                 (2, '2026-08-27T10:00:00', N'Plava cipela', 8.90, NULL),                 (1, '2026-08-27T09:00:00', N'Crna čizma', 12.50, N'akcija'),                 (3, '2026-08-27T11:00:00', N'Žuta sandala', 15.00, N'novo');             """,             """             CREATE TABLE [dbo].[Каталог] (                 [IDArtikal] BIGINT NOT NULL PRIMARY KEY,                 [Naziv] NVARCHAR(100) NOT NULL             );             """,             """             INSERT INTO [dbo].[Каталог] ([IDArtikal], [Naziv]) VALUES                 (10, N'Проба');             """         };          foreach (var statement in setupStatements)         {             await using var setup = new SqlCommand(statement, seeded);             await setup.ExecuteNonQueryAsync();         }          return dbBuilder.ConnectionString;     } }  internal sealed class ListLogger<T> : ILogger {     private readonly List<string> _messages = [];      public IReadOnlyList<string> Messages => _messages;      public IDisposable BeginScope<TState>(TState state) where TState : notnull => NullScope.Instance;      public bool IsEnabled(LogLevel logLevel) => true;      public void Log<TState>(         LogLevel logLevel,         EventId eventId,         TState state,         Exception? exception,         Func<TState, Exception?, string> formatter)     {         _messages.Add(formatter(state, exception));     }      private sealed class NullScope : IDisposable     {         public static readonly NullScope Instance = new();          public void Dispose()         {         }     } }